/* From Uiverse.io by Yaya12085 - Tags: card */
.__UIV_SCOPE__ .card {
  padding: 10px;
  max-width: 260px;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  background-color: rgb(255, 255, 255);
  font-family: sans-serif;
}

.__UIV_SCOPE__ .content {
  margin-top: 1rem;
}

.__UIV_SCOPE__ .content .header {
  margin-top: 0.5rem;
}

.__UIV_SCOPE__ .image {
  width: 100%;
  height: 150px;
  border-radius: 4px;
  background-color: rgb(205, 235, 255);
  padding: 9px;
}

.__UIV_SCOPE__ .tag {
  text-transform: capitalize;
  background-color: rgba(0, 0, 0, 0.425);
  padding: 2px 8px;
  border-radius: 4px;
  color: #fff;
}

.__UIV_SCOPE__ .date {
  display: flex;
  font-size: 0.75rem;
  line-height: 1rem;
  align-items: center;
  margin: 2px;
}

.__UIV_SCOPE__ .title {
  display: block;
  font-size: 1.25rem;
  line-height: 1.35rem;
  font-weight: 600;
  padding-bottom: 5px;
  padding-top: 14px;
}

.__UIV_SCOPE__ .description {
  line-height: 1.375;
}
